import React from 'react';

interface MessageIconProps {
  size?: number;
  className?: string;
}

const MessageIcon: React.FC<MessageIconProps> = ({ size = 26, className = '' }) => (
  <svg
    width={size}
    height={size}
    viewBox="0 0 100 100"
    fill="none"
    xmlns="http://www.w3.org/2000/svg"
    className={className}
    style={{ overflow: 'visible', filter: 'drop-shadow(0px 3px 6px rgba(0,0,0,0.12))' }}
  >
    <defs>
      {/* Back bubble gradient (Pink/Orange) */}
      <linearGradient id="bubbleBack" x1="20" y1="10" x2="80" y2="70" gradientUnits="userSpaceOnUse">
        <stop offset="0%" stopColor="#FF6B6B" />
        <stop offset="100%" stopColor="#FF8E53" />
      </linearGradient>

      {/* Front bubble gradient (Vibrant Blue/Cyan) */}
      <linearGradient id="bubbleFront" x1="10" y1="30" x2="70" y2="90" gradientUnits="userSpaceOnUse">
        <stop offset="0%" stopColor="#3B82F6" />
        <stop offset="100%" stopColor="#06B6D4" />
      </linearGradient>

      {/* Glossy highlight gradient */}
      <linearGradient id="glossy" x1="20" y1="30" x2="50" y2="70" gradientUnits="userSpaceOnUse">
        <stop offset="0%" stopColor="white" stopOpacity="0.6" />
        <stop offset="100%" stopColor="white" stopOpacity="0.0" />
      </linearGradient>
    </defs>

    {/* Back Bubble (Pinkish) */}
    <path
      d="M85 35C85 18.43 71.57 5 55 5C38.43 5 25 18.43 25 35C25 40.5 26.5 45.65 29.1 50.11L25 65L39.89 60.9C44.35 63.5 49.5 65 55 65C71.57 65 85 51.57 85 35Z"
      fill="url(#bubbleBack)"
    />

    {/* Front Bubble (Bluish) */}
    <path
      d="M75 60C75 43.43 61.57 30 45 30C28.43 30 15 43.43 15 60C15 65.5 16.5 70.65 19.1 75.11L15 90L29.89 85.9C34.35 88.5 39.5 90 45 90C61.57 90 75 76.57 75 60Z"
      fill="url(#bubbleFront)"
    />

    {/* Front Bubble Core Highlight (Gloss) */}
    <path
      d="M25 45C33 34 55 32 65 42C67 44 68.5 47 69.5 50C65 38 45 38 22 55C22 52 23 48 25 45Z"
      fill="url(#glossy)"
    />

    {/* Typing Dots inside Front Bubble */}
    <circle cx="33" cy="61" r="5" fill="white" />
    <circle cx="45" cy="61" r="5" fill="white" />
    <circle cx="57" cy="61" r="5" fill="white" />
  </svg>
);

export default MessageIcon;
